0.001  & 0.728 & 0.145 & $+0.004$ \\
0.01   & 0.738 & 0.137 & $+0.014$ \\
\textbf{0.1} & \textbf{0.763} & \textbf{0.121} & $+0.039$ \\
1.0    & 0.731 & 0.141 & $+0.007$ \\
